import json
d=json.load(open('hig_vo.json'))
def walk(n,out):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='heading': out.append('\n## '+n.get('text','')+'\n')
        if t=='text': out.append(n.get('text',''))
        if t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        for k,v in n.items():
            if k in ('content','inlineContent','sections','primaryContentSections','items','columns','rows'): walk(v,out)
    elif isinstance(n,list):
        for x in n: walk(x,out)
out=[]
